const packageJsonRaw = $('HTTP: Fetch package.json').first().json;
const packageLockRaw = $('HTTP: Fetch package-lock.json').first().json;
const requirementsRaw = $('HTTP: Fetch requirements.txt').first().json;
const existingIssues = $('HTTP: Fetch Existing Dependency Issues').first().json;
const initContext = $('Set: Initialize Audit Context').first().json;

// Parse package.json
let packageJson = {};
try {
  packageJson = typeof packageJsonRaw.data === 'string' 
    ? JSON.parse(packageJsonRaw.data) 
    : packageJsonRaw.data || {};
} catch (e) {
  packageJson = { dependencies: {}, devDependencies: {} };
}

// Parse package-lock.json (for exact versions)
let packageLock = {};
try {
  packageLock = typeof packageLockRaw.data === 'string'
    ? JSON.parse(packageLockRaw.data)
    : packageLockRaw.data || {};
} catch (e) {
  packageLock = { packages: {} };
}

// Parse requirements.txt
let pythonDeps = [];
const reqContent = requirementsRaw.data || '';
if (typeof reqContent === 'string') {
  pythonDeps = reqContent.split('\n')
    .map(line => line.trim())
    .filter(line => line && !line.startsWith('#'))
    .map(line => {
      const match = line.match(/^([a-zA-Z0-9_-]+)([>=<~!]+)?(.+)?$/);
      return match ? {
        name: match[1],
        constraint: match[2] || '',
        version: match[3]?.trim() || 'latest',
        ecosystem: 'pip'
      } : null;
    })
    .filter(Boolean);
}

// Build NPM dependencies list
const npmDeps = [];
const deps = packageJson.dependencies || {};
const devDeps = packageJson.devDependencies || {};

for (const [name, version] of Object.entries(deps)) {
  npmDeps.push({
    name,
    version: version.replace(/^[\^~]/, ''),
    constraint: version.charAt(0),
    isDev: false,
    ecosystem: 'npm'
  });
}

for (const [name, version] of Object.entries(devDeps)) {
  npmDeps.push({
    name,
    version: version.replace(/^[\^~]/, ''),
    constraint: version.charAt(0),
    isDev: true,
    ecosystem: 'npm'
  });
}

// Get existing issue summaries to avoid duplicates
const existingIssueSummaries = new Set();
(existingIssues?.issues || []).forEach(issue => {
  if (issue.fields?.summary) {
    existingIssueSummaries.add(issue.fields.summary.toLowerCase());
  }
});

return {
  json: {
    auditId: initContext.auditId,
    auditDate: initContext.auditDate,
    npmDeps: npmDeps,
    pythonDeps: pythonDeps,
    existingIssueSummaries: Array.from(existingIssueSummaries),
    totalNpmDeps: npmDeps.length,
    totalPythonDeps: pythonDeps.length
  }
};

// Prepare NPM packages for registry lookup
const data = $json;
const topPackages = data.npmDeps.slice(0, 30); // Limit for API efficiency

return topPackages.map(pkg => ({
  json: {
    ...pkg,
    auditId: data.auditId,
    lookupUrl: `https://registry.npmjs.org/${pkg.name}`
  }
}));

// Prepare Python packages for PyPI lookup
const data = $json;
const packages = data.pythonDeps || [];

return packages.map(pkg => ({
  json: {
    ...pkg,
    auditId: data.auditId,
    lookupUrl: `https://pypi.org/pypi/${pkg.name}/json`
  }
}));

const pkg = $json;
const auditId = $('Code: Prepare NPM Packages').first().json.auditId;

let result = {
  name: pkg.name,
  currentVersion: pkg.version,
  ecosystem: 'npm',
  isDev: pkg.isDev,
  status: 'unknown',
  latestVersion: null,
  updateType: null,
  isOutdated: false,
  vulnerability: null,
  auditId: auditId
};

try {
  // Parse registry response
  const latestVersion = pkg['dist-tags']?.latest;
  const versions = Object.keys(pkg.versions || {});

  if (latestVersion) {
    result.latestVersion = latestVersion;

    // Simple version comparison
    const currentParts = (result.currentVersion || '0.0.0').split('.').map(Number);
    const latestParts = latestVersion.split('.').map(Number);

    if (latestParts[0] > currentParts[0]) {
      result.updateType = 'major';
      result.isOutdated = true;
      result.status = 'outdated-major';
    } else if (latestParts[1] > currentParts[1]) {
      result.updateType = 'minor';
      result.isOutdated = true;
      result.status = 'outdated-minor';
    } else if (latestParts[2] > currentParts[2]) {
      result.updateType = 'patch';
      result.isOutdated = true;
      result.status = 'outdated-patch';
    } else {
      result.status = 'current';
    }
  }

  // Check for deprecated
  if (pkg.deprecated) {
    result.status = 'deprecated';
    result.vulnerability = { severity: 'high', message: pkg.deprecated };
  }

} catch (e) {
  result.status = 'error';
  result._error = e.message;
}

return { json: result };

const pkg = $json;
const auditId = $('Code: Prepare Python Packages').first().json.auditId;

let result = {
  name: pkg.name,
  currentVersion: pkg.version,
  ecosystem: 'pip',
  isDev: false,
  status: 'unknown',
  latestVersion: null,
  updateType: null,
  isOutdated: false,
  vulnerability: null,
  auditId: auditId
};

try {
  const info = pkg.info || {};
  const releases = Object.keys(pkg.releases || {});

  // Get latest stable version (exclude pre-releases)
  const stableReleases = releases
    .filter(v => !v.includes('a') && !v.includes('b') && !v.includes('rc'))
    .sort((a, b) => {
      const aParts = a.split('.').map(Number);
      const bParts = b.split('.').map(Number);
      for (let i = 0; i < Math.max(aParts.length, bParts.length); i++) {
        if ((aParts[i] || 0) !== (bParts[i] || 0)) {
          return (bParts[i] || 0) - (aParts[i] || 0);
        }
      }
      return 0;
    });

  const latestVersion = stableReleases[0] || info.version;

  if (latestVersion) {
    result.latestVersion = latestVersion;

    // Simple version comparison
    const currentParts = (result.currentVersion || '0.0.0').split('.').map(Number);
    const latestParts = latestVersion.split('.').map(Number);

    if (latestParts[0] > currentParts[0]) {
      result.updateType = 'major';
      result.isOutdated = true;
      result.status = 'outdated-major';
    } else if (latestParts[1] > currentParts[1]) {
      result.updateType = 'minor';
      result.isOutdated = true;
      result.status = 'outdated-minor';
    } else if ((latestParts[2] || 0) > (currentParts[2] || 0)) {
      result.updateType = 'patch';
      result.isOutdated = true;
      result.status = 'outdated-patch';
    } else {
      result.status = 'current';
    }
  }

} catch (e) {
  result.status = 'error';
  result._error = e.message;
}

return { json: result };

const pkg = $json;
const vulnerabilities = pkg.vulns || [];

let result = {
  name: $('Code: Analyze NPM Versions').item.json.name,
  currentVersion: $('Code: Analyze NPM Versions').item.json.currentVersion,
  latestVersion: $('Code: Analyze NPM Versions').item.json.latestVersion,
  ecosystem: 'npm',
  isDev: $('Code: Analyze NPM Versions').item.json.isDev,
  status: $('Code: Analyze NPM Versions').item.json.status,
  updateType: $('Code: Analyze NPM Versions').item.json.updateType,
  isOutdated: $('Code: Analyze NPM Versions').item.json.isOutdated,
  auditId: $('Code: Analyze NPM Versions').item.json.auditId
};

if (vulnerabilities.length > 0) {
  // Get highest severity
  const severityOrder = { 'CRITICAL': 0, 'HIGH': 1, 'MODERATE': 2, 'MEDIUM': 2, 'LOW': 3 };
  const sortedVulns = vulnerabilities.sort((a, b) => 
    (severityOrder[a.severity] || 4) - (severityOrder[b.severity] || 4)
  );

  result.vulnerability = {
    count: vulnerabilities.length,
    severity: sortedVulns[0]?.severity || 'UNKNOWN',
    ids: vulnerabilities.map(v => v.id).slice(0, 5),
    summary: sortedVulns[0]?.summary || 'See vulnerability database'
  };
  result.status = 'vulnerable';
}

return { json: result };

const pkg = $json;
const vulnerabilities = pkg.vulns || [];

let result = {
  name: $('Code: Analyze Python Versions').item.json.name,
  currentVersion: $('Code: Analyze Python Versions').item.json.currentVersion,
  latestVersion: $('Code: Analyze Python Versions').item.json.latestVersion,
  ecosystem: 'pip',
  isDev: false,
  status: $('Code: Analyze Python Versions').item.json.status,
  updateType: $('Code: Analyze Python Versions').item.json.updateType,
  isOutdated: $('Code: Analyze Python Versions').item.json.isOutdated,
  auditId: $('Code: Analyze Python Versions').item.json.auditId
};

if (vulnerabilities.length > 0) {
  const severityOrder = { 'CRITICAL': 0, 'HIGH': 1, 'MODERATE': 2, 'MEDIUM': 2, 'LOW': 3 };
  const sortedVulns = vulnerabilities.sort((a, b) => 
    (severityOrder[a.severity] || 4) - (severityOrder[b.severity] || 4)
  );

  result.vulnerability = {
    count: vulnerabilities.length,
    severity: sortedVulns[0]?.severity || 'UNKNOWN',
    ids: vulnerabilities.map(v => v.id).slice(0, 5),
    summary: sortedVulns[0]?.summary || 'See vulnerability database'
  };
  result.status = 'vulnerable';
}

return { json: result };

const allPackages = $input.all().map(i => i.json);
const auditId = allPackages[0]?.auditId || 'unknown';

// Categorize packages
const vulnerable = allPackages.filter(p => p.vulnerability);
const outdatedMajor = allPackages.filter(p => p.updateType === 'major' && !p.vulnerability);
const outdatedMinor = allPackages.filter(p => p.updateType === 'minor' && !p.vulnerability);
const outdatedPatch = allPackages.filter(p => p.updateType === 'patch' && !p.vulnerability);
const current = allPackages.filter(p => p.status === 'current');
const deprecated = allPackages.filter(p => p.status === 'deprecated');

// Count by ecosystem
const npmCount = allPackages.filter(p => p.ecosystem === 'npm').length;
const pipCount = allPackages.filter(p => p.ecosystem === 'pip').length;

// Calculate security score (100 = no vulnerabilities, 0 = critical issues)
let securityScore = 100;
vulnerable.forEach(v => {
  const severity = v.vulnerability?.severity || 'LOW';
  if (severity === 'CRITICAL') securityScore -= 25;
  else if (severity === 'HIGH') securityScore -= 15;
  else if (severity === 'MODERATE' || severity === 'MEDIUM') securityScore -= 10;
  else securityScore -= 5;
});
deprecated.forEach(() => securityScore -= 10);
securityScore = Math.max(0, securityScore);

const summary = {
  auditId: auditId,
  totalPackages: allPackages.length,
  npmPackages: npmCount,
  pythonPackages: pipCount,
  vulnerableCount: vulnerable.length,
  deprecatedCount: deprecated.length,
  outdatedMajorCount: outdatedMajor.length,
  outdatedMinorCount: outdatedMinor.length,
  outdatedPatchCount: outdatedPatch.length,
  currentCount: current.length,
  securityScore: securityScore,
  hasCriticalIssues: vulnerable.some(v => 
    ['CRITICAL', 'HIGH'].includes(v.vulnerability?.severity)
  )
};

return {
  json: {
    summary: summary,
    vulnerable: vulnerable,
    deprecated: deprecated,
    outdatedMajor: outdatedMajor,
    outdatedMinor: outdatedMinor,
    allPackages: allPackages
  }
};

const data = $json;
const summary = data.summary;

// Build vulnerability list
const vulnList = data.vulnerable.map(v => 
  `- ${v.name}@${v.currentVersion} (${v.ecosystem}): ${v.vulnerability?.severity} - ${v.vulnerability?.summary || 'See CVE'}`
).join('\n');

// Build deprecated list
const deprecatedList = data.deprecated.map(d =>
  `- ${d.name}@${d.currentVersion}`
).join('\n');

// Build major updates list
const majorList = data.outdatedMajor.slice(0, 10).map(m =>
  `- ${m.name}: ${m.currentVersion} -> ${m.latestVersion}`
).join('\n');

const prompt = `You are a security-focused DevOps engineer reviewing dependency audit results for the SwjshAlgoKnife trading platform.

AUDIT SUMMARY:
- Total Packages: ${summary.totalPackages} (NPM: ${summary.npmPackages}, Python: ${summary.pythonPackages})
- Vulnerable: ${summary.vulnerableCount}
- Deprecated: ${summary.deprecatedCount}
- Major Updates Available: ${summary.outdatedMajorCount}
- Minor Updates Available: ${summary.outdatedMinorCount}
- Patch Updates Available: ${summary.outdatedPatchCount}
- Security Score: ${summary.securityScore}/100

VULNERABLE PACKAGES:
${vulnList || 'None found'}

DEPRECATED PACKAGES:
${deprecatedList || 'None found'}

MAJOR VERSION UPDATES AVAILABLE:
${majorList || 'None found'}

ANALYZE AND PROVIDE:

1. **Risk Assessment**: Overall security posture (Critical/High/Medium/Low)

2. **Immediate Actions** (must-fix within 24h):
   - Package name
   - Current -> Required version
   - Why urgent
   - Breaking change risk (High/Medium/Low)

3. **Scheduled Updates** (within 1 week):
   - Package updates to plan
   - Any compatibility concerns

4. **Recommendations**:
   - Dependency management improvements
   - Security scanning suggestions

5. **Jira Tickets to Create**:
   - Only for critical/high priority issues
   - Include clear acceptance criteria

Respond as JSON:
{
  "riskLevel": "Critical|High|Medium|Low",
  "riskSummary": "string",
  "immediateActions": [
    {
      "package": "string",
      "currentVersion": "string",
      "targetVersion": "string",
      "urgency": "string",
      "breakingRisk": "High|Medium|Low"
    }
  ],
  "scheduledUpdates": [
    {
      "package": "string",
      "update": "string",
      "notes": "string"
    }
  ],
  "recommendations": ["string"],
  "jiraTickets": [
    {
      "summary": "string",
      "description": "string",
      "priority": "Highest|High|Medium",
      "labels": ["string"]
    }
  ],
  "sendAlert": boolean
}`;

return {
  json: {
    ...data,
    claudePrompt: prompt
  }
};

const input = $json;
let analysis;

try {
  const responseText = input.content?.[0]?.text || input.content || '';
  const jsonMatch = responseText.match(/\{[\s\S]*\}/);
  if (jsonMatch) {
    analysis = JSON.parse(jsonMatch[0]);
  } else {
    throw new Error('No JSON found');
  }
} catch (e) {
  analysis = {
    riskLevel: input.summary?.hasCriticalIssues ? 'High' : 'Medium',
    riskSummary: 'Unable to parse AI analysis - manual review required',
    immediateActions: [],
    scheduledUpdates: [],
    recommendations: ['Review audit results manually'],
    jiraTickets: [],
    sendAlert: input.summary?.hasCriticalIssues || false,
    _parseError: e.message
  };
}

return {
  json: {
    summary: input.summary,
    vulnerable: input.vulnerable,
    deprecated: input.deprecated,
    analysis: analysis
  }
};

const data = $('Code: Parse Claude Response').first().json;
const tickets = data.analysis?.jiraTickets || [];

return tickets.map(ticket => ({
  json: {
    summary: ticket.summary,
    description: ticket.description,
    priority: ticket.priority,
    labels: [...(ticket.labels || []), 'dependency-audit', 'security', 'automated'],
    auditId: data.summary.auditId
  }
}));

const error = $json;

return {
  json: {
    workflowName: 'Dependency Auditor',
    errorMessage: error.execution?.error?.message || 'Unknown error',
    errorNode: error.execution?.lastNodeExecuted || 'unknown',
    timestamp: new Date().toISOString(),
    executionId: error.execution?.id || 'unknown'
  }
};
